<script setup>
import { Head, Link, useForm, usePage } from '@inertiajs/vue3'
import { ref, toRefs } from 'vue'
import AppShell from '../../Layouts/AppShell.vue'
defineOptions({ layout: AppShell })
const props = defineProps({ title:String, description:String, surface:String, kind:String, items:Object, assets:Array, locations:Array, periods:Array, templates:Array, roles:Array, inventoryItems:Array, discrepancies:Array, errors:Array, approval:Object, filters:Object })
const { surface, kind } = toRefs(props)
const page=usePage()
const can=(p)=>page.props.permissions?.[p]===true
const form=useForm({ name:'', period_label:'', reference_at:new Date().toISOString().slice(0,10), code:'', location_type:'room', type:'unit', party_type:'organizational_unit', membership_id:'', organizational_unit_id:'', asset_id:'', maintenance_type:'', reason:'', period_year:new Date().getFullYear(), year:new Date().getFullYear(), period_type:'year', period_number:'', start_date:new Date().toISOString().slice(0,10), end_date:new Date().toISOString().slice(0,10), action:'', idempotency_key:crypto.randomUUID(), notes:'', period_id:'', template_version_id:'', email:'', role_id:'' })
const post=(url,data=form)=>data.post(url,{preserveScroll:true})
const selectedAssets=ref([])
const labelForm=useForm({asset_uuids:[]})
const filterLabelForm=useForm({filter_q:props.filters?.q||''})
const prepareLabels=()=>{ labelForm.asset_uuids=[...selectedAssets.value]; labelForm.post('/assets/labels/prepare') }
const prepareFilteredLabels=()=>{ filterLabelForm.filter_q=props.filters?.q||''; filterLabelForm.post('/assets/labels/prepare') }
const label=(v)=>({draft:'Draf',active:'Aktif',pending:'Menunggu',approved:'Disetujui',rejected:'Ditolak',finalized:'Final',review:'Dalam review',open:'Terbuka',matched:'Cocok',verified:'Terverifikasi',unverified:'Belum diverifikasi',good:'Baik',fair:'Rusak ringan',damaged:'Rusak',broken:'Rusak berat',prepared:'Siap diperiksa',in_progress:'Berjalan',completed:'Selesai'}[v]||v||'-')
const kindName=(v)=>({locations:'Lokasi','funding-sources':'Sumber dana','organizational-units':'Unit organisasi','responsible-parties':'Penanggung jawab',classifications:'Klasifikasi',maintenance:'Pemeliharaan',mutations:'Mutasi',utilization:'Pemanfaatan',safeguarding:'Pengamanan',valuation:'Penilaian',transfers:'Pemindahan',disposals:'Penghapusan',usage:'Penetapan penggunaan',members:'Pengguna & peran',audit:'Audit aktivitas',settings:'Pengaturan desa'}[v]||v)
const pageTitle=()=>surface.value==='master-data'?kindName(props.kind):surface.value==='administration'?kindName(props.kind):props.title
const eyebrow=()=>surface.value==='master-data'?'Master Data':surface.value==='administration'?'Administrasi':surface.value==='approvals'||surface.value==='approval-detail'?'Persetujuan':surface.value==='reports'?'Pelaporan':surface.value==='inventory'?'Inventarisasi':'Pengelolaan Aset'
</script>
<template><Head :title="pageTitle()" /><main class="mx-auto max-w-7xl space-y-7 px-4 py-8 sm:px-6 lg:py-10">
<header><p class="text-xs font-bold uppercase tracking-[0.2em] text-blue-700">{{ eyebrow() }}</p><h1 class="mt-2 text-3xl font-bold tracking-tight sm:text-4xl">{{ pageTitle() }}</h1><p v-if="description" class="mt-2 max-w-3xl text-slate-600">{{ description }}</p></header>

<section v-if="surface==='assets'" class="space-y-4"><form method="get" class="flex flex-wrap gap-2 rounded-2xl border border-slate-200 bg-white p-3 shadow-sm"><input name="q" aria-label="Cari aset" class="min-w-[14rem] flex-1 border-0 bg-transparent px-2 py-2 outline-none" placeholder="Cari nama, kode, atau NUP"><button class="rounded-lg border border-slate-300 px-4 py-2 text-sm font-bold">Cari</button><button v-if="can('documents.manage')" type="button" :disabled="!selectedAssets.length||labelForm.processing" class="rounded-lg border border-slate-300 px-4 py-2 text-sm font-bold disabled:cursor-not-allowed disabled:opacity-40" @click="prepareLabels">Cetak label ({{ selectedAssets.length }})</button><button v-if="can('documents.manage')&&filters?.q" type="button" :disabled="filterLabelForm.processing" class="rounded-lg border border-slate-300 px-4 py-2 text-sm font-bold disabled:opacity-40" @click="prepareFilteredLabels">Cetak semua hasil filter</button><Link v-if="can('assets.create')" href="/assets/create" class="rounded-lg bg-[#0B2E5B] px-4 py-2 text-sm font-bold text-white">Tambah aset</Link></form><div v-if="labelForm.errors.asset || filterLabelForm.errors.asset || filterLabelForm.errors.filter_q" class="rounded-xl border border-red-200 bg-red-50 px-4 py-3 text-sm font-medium text-red-800">{{ labelForm.errors.asset || filterLabelForm.errors.asset || filterLabelForm.errors.filter_q }}</div><div class="overflow-x-auto rounded-2xl border border-slate-200 bg-white shadow-sm"><table class="w-full min-w-[46rem] text-left text-sm"><thead class="bg-slate-50 text-xs uppercase tracking-wide text-slate-500"><tr><th v-if="can('documents.manage')" class="w-12 p-4"><span class="sr-only">Pilih</span></th><th class="p-4">Aset</th><th class="p-4">Klasifikasi</th><th class="p-4">Kondisi</th><th class="p-4">Status</th></tr></thead><tbody class="divide-y divide-slate-100"><tr v-for="item in items?.data" :key="item.uuid"><td v-if="can('documents.manage')" class="p-4"><input v-model="selectedAssets" type="checkbox" :value="item.uuid" :aria-label="'Pilih '+item.name+' untuk label'"></td><td class="p-4"><Link :href="`/assets/${item.uuid}`" class="font-bold text-blue-800">{{ item.name }}</Link><p class="mt-1 text-xs text-slate-500">{{ item.asset_code||'Tanpa kode' }}  -  {{ item.register_number||'Tanpa NUP' }}</p></td><td class="p-4">{{ item.classification?.name||'-' }}</td><td class="p-4"><span class="rounded-full bg-slate-100 px-2.5 py-1 text-xs font-semibold">{{ label(item.condition) }}</span></td><td class="p-4">{{ label(item.lifecycle_status) }}</td></tr></tbody></table><p v-if="!items?.data?.length" class="p-10 text-center text-slate-500">Belum ada aset pada desa aktif.</p></div></section>

<section v-else-if="surface==='inventory'" class="space-y-5"><div class="grid gap-4 sm:grid-cols-3"><article class="rounded-2xl border bg-white p-5 shadow-sm"><p class="text-sm text-slate-500">Sesi inventarisasi</p><strong class="mt-2 block text-3xl">{{ items?.total??items?.data?.length??0 }}</strong></article><article class="rounded-2xl border bg-white p-5 shadow-sm"><p class="text-sm text-slate-500">Item observasi</p><strong class="mt-2 block text-3xl">{{ inventoryItems?.length??0 }}</strong></article><article class="rounded-2xl border border-amber-200 bg-amber-50 p-5"><p class="text-sm text-amber-800">Selisih terbuka</p><strong class="mt-2 block text-3xl text-amber-950">{{ discrepancies?.length??0 }}</strong></article></div><details class="rounded-2xl border border-slate-200 bg-white p-5 shadow-sm"><summary class="cursor-pointer font-bold">Buat sesi inventarisasi baru</summary><form class="mt-5 grid gap-3 md:grid-cols-4" @submit.prevent="post('/inventory')"><input v-model="form.name" required class="rounded-lg border px-3 py-2.5" placeholder="Nama sesi"><input v-model="form.period_label" required class="rounded-lg border px-3 py-2.5" placeholder="Periode, mis. Semester II 2026"><input v-model="form.reference_at" required type="date" class="rounded-lg border px-3 py-2.5"><button class="rounded-lg bg-[#0B2E5B] px-4 py-2.5 font-bold text-white">Buat sesi</button></form></details><section class="overflow-hidden rounded-2xl border bg-white shadow-sm"><div class="border-b px-5 py-4"><h2 class="font-bold">Sesi inventarisasi</h2></div><article v-for="item in items?.data" :key="item.uuid" class="flex flex-wrap items-center justify-between gap-4 border-b border-slate-100 p-5 last:border-0"><div><strong>{{ item.name }}</strong><p class="mt-1 text-sm text-slate-500">{{ item.period_label }}  -  {{ label(item.status) }}</p></div><div class="flex gap-2"><form @submit.prevent="post(`/inventory/${item.uuid}/freeze`)"><button class="rounded-lg border px-3 py-2 text-sm font-semibold">Siapkan data</button></form><form @submit.prevent="post(`/inventory/${item.uuid}/finalize`)"><button class="rounded-lg bg-[#0B2E5B] px-3 py-2 text-sm font-semibold text-white">Finalisasi</button></form></div></article></section><section v-if="discrepancies?.length" class="rounded-2xl border border-amber-200 bg-amber-50 p-5"><h2 class="font-bold text-amber-950">Selisih yang perlu direkonsiliasi</h2><article v-for="item in discrepancies" :key="item.id" class="mt-4 flex flex-wrap items-center justify-between gap-3 border-t border-amber-200 pt-4"><div><strong class="text-amber-950">{{ label(item.discrepancy_type) }}</strong><p class="text-sm text-amber-800">{{ item.description }}</p></div><form @submit.prevent="post(`/inventory/discrepancies/${item.id}/reconcile`,Object.assign(form,{resolution_type:'no_change',idempotency_key:crypto.randomUUID()}))"><button class="rounded-lg border border-amber-300 bg-white px-3 py-2 text-sm font-semibold">Rekonsiliasi</button></form></article></section></section>

<section v-else-if="surface==='approvals'" class="overflow-hidden rounded-2xl border bg-white shadow-sm"><div class="border-b px-5 py-4"><h2 class="font-bold">Kotak masuk persetujuan</h2><p class="mt-1 text-sm text-slate-500">Tinjau permohonan sebelum mengambil keputusan.</p></div><article v-for="item in items?.data" :key="item.id" class="flex flex-wrap items-center justify-between gap-4 border-b border-slate-100 p-5 last:border-0"><div><Link :href="`/approvals/${item.id}`" class="font-bold text-blue-800">Permohonan #{{ item.id }}</Link><p class="mt-1 text-sm text-slate-500">{{ label(item.status) }}  -  {{ item.submitted_at||'Belum diajukan' }}</p></div><div v-if="item.status==='pending'&&can('approvals.action')" class="flex gap-2"><form @submit.prevent="post(`/approvals/${item.id}/action`,Object.assign(form,{action:'approve',idempotency_key:crypto.randomUUID()}))"><button class="rounded-lg bg-[#0B2E5B] px-3 py-2 text-sm font-bold text-white">Setujui</button></form><form @submit.prevent="post(`/approvals/${item.id}/action`,Object.assign(form,{action:'reject',idempotency_key:crypto.randomUUID()}))"><button class="rounded-lg border px-3 py-2 text-sm font-semibold">Tolak</button></form></div></article><p v-if="!items?.data?.length" class="p-10 text-center text-slate-500">Tidak ada permohonan persetujuan.</p></section>

<section v-else-if="surface==='approval-detail'" class="space-y-4"><Link href="/approvals" class="text-sm font-semibold text-blue-700"> -  Kembali ke persetujuan</Link><section class="rounded-2xl border bg-white p-6 shadow-sm"><p class="text-sm text-slate-500">Status permohonan</p><p class="mt-1 text-2xl font-bold">{{ label(approval.status) }}</p><h2 class="mt-6 font-bold">Tahapan persetujuan</h2><ol class="mt-3 space-y-3"><li v-for="step in approval.steps" :key="step.id" class="rounded-xl bg-slate-50 p-4 text-sm"><strong>Tahap {{ step.sequence }}</strong><span class="ml-2">{{ label(step.status) }}</span></li></ol></section></section>

<section v-else-if="surface==='reports'" class="space-y-5"><div class="grid gap-4 sm:grid-cols-3"><article class="rounded-2xl border bg-white p-5 shadow-sm"><p class="text-sm text-slate-500">Periode tersedia</p><strong class="mt-2 block text-3xl">{{ periods?.length??0 }}</strong></article><article class="rounded-2xl border bg-white p-5 shadow-sm"><p class="text-sm text-slate-500">Laporan</p><strong class="mt-2 block text-3xl">{{ items?.total??items?.data?.length??0 }}</strong></article><article class="rounded-2xl border bg-white p-5 shadow-sm"><p class="text-sm text-slate-500">Template aktif</p><strong class="mt-2 block text-3xl">{{ templates?.length??0 }}</strong></article></div><details class="rounded-2xl border bg-white p-5 shadow-sm"><summary class="cursor-pointer font-bold">Buat periode pelaporan</summary><form class="mt-5 grid gap-3 md:grid-cols-5" @submit.prevent="post('/reports/periods')"><input v-model="form.year" type="number" required class="rounded-lg border px-3 py-2.5" placeholder="Tahun"><select v-model="form.period_type" class="rounded-lg border px-3 py-2.5"><option value="year">Tahunan</option><option value="semester">Semester</option></select><input v-model="form.start_date" type="date" required class="rounded-lg border px-3 py-2.5"><input v-model="form.end_date" type="date" required class="rounded-lg border px-3 py-2.5"><button class="rounded-lg bg-[#0B2E5B] px-4 py-2.5 font-bold text-white">Buat periode</button></form></details><section class="overflow-hidden rounded-2xl border bg-white shadow-sm"><div class="border-b px-5 py-4"><h2 class="font-bold">Daftar laporan</h2></div><article v-for="item in items?.data" :key="item.id" class="flex flex-wrap items-center justify-between gap-4 border-b p-5 last:border-0"><div><strong>Laporan #{{ item.id }}</strong><p class="mt-1 text-sm text-slate-500">{{ label(item.status) }}  -  Revisi {{ item.revision_number }}</p></div><div class="flex gap-2"><form v-if="item.status==='draft'" @submit.prevent="post(`/reports/${item.id}/review`)"><button class="rounded-lg border px-3 py-2 text-sm font-semibold">Ajukan review</button></form><form v-if="item.status==='review'" @submit.prevent="post(`/reports/${item.id}/finalize`)"><button class="rounded-lg bg-[#0B2E5B] px-3 py-2 text-sm font-bold text-white">Finalisasi</button></form><Link v-if="item.status==='finalized'" :href="`/reports/${item.id}/export`" class="rounded-lg border px-3 py-2 text-sm font-semibold">Ekspor</Link></div></article><p v-if="!items?.data?.length" class="p-10 text-center text-slate-500">Belum ada laporan.</p></section></section>

<section v-else-if="surface==='master-data'" class="space-y-5"><div class="grid gap-3 sm:grid-cols-2 lg:grid-cols-3"><article v-for="item in items?.data" :key="item.id" class="rounded-2xl border bg-white p-5 shadow-sm"><p class="text-xs font-semibold uppercase tracking-wide text-slate-500">{{ item.code||item.party_type||'Referensi' }}</p><h2 class="mt-1 font-bold">{{ item.name||item.type||'Penanggung jawab' }}</h2><p class="mt-2 text-sm text-slate-500">{{ label(item.status) }}</p></article></div><form v-if="kind!=='classifications'" class="grid gap-3 rounded-2xl border bg-white p-5 shadow-sm md:grid-cols-4" @submit.prevent="post(`/master-data/${kind}`)"><input v-if="kind!=='responsible-parties'" v-model="form.code" required class="rounded-lg border px-3 py-2.5" placeholder="Kode"><input v-if="kind!=='responsible-parties'" v-model="form.name" required class="rounded-lg border px-3 py-2.5" placeholder="Nama"><input v-if="kind==='locations'" v-model="form.location_type" required class="rounded-lg border px-3 py-2.5" placeholder="Jenis lokasi"><input v-if="kind==='organizational-units'" v-model="form.type" required class="rounded-lg border px-3 py-2.5" placeholder="Jenis unit"><button class="rounded-lg bg-[#0B2E5B] px-4 py-2.5 font-bold text-white">Tambah {{ kindName(kind).toLowerCase() }}</button></form></section>

<section v-else-if="surface==='administration'" class="space-y-5"><section class="overflow-hidden rounded-2xl border bg-white shadow-sm"><article v-for="item in items?.data" :key="item.id" class="border-b border-slate-100 p-5 last:border-0"><strong>{{ item.user?.name||item.action||item.code||'Pengaturan desa' }}</strong><p class="mt-1 text-sm text-slate-500">{{ item.user?.email||item.occurred_at||item.name||'' }}</p><p v-if="item.roles?.length" class="mt-2 text-xs text-slate-500">{{ item.roles.map(r=>r.name).join(', ') }}</p></article></section><form v-if="kind==='members'" class="grid gap-3 rounded-2xl border bg-white p-5 shadow-sm md:grid-cols-3" @submit.prevent="post('/administration/memberships')"><input v-model="form.email" type="email" required class="rounded-lg border px-3 py-2.5" placeholder="Email pengguna"><select v-model="form.role_id" required class="rounded-lg border px-3 py-2.5"><option value="">Pilih peran</option><option v-for="role in roles" :key="role.id" :value="role.id">{{ role.name }}</option></select><button class="rounded-lg bg-[#0B2E5B] px-4 py-2.5 font-bold text-white">Tambahkan pengguna</button></form></section>

<section v-else-if="surface==='lifecycle'" class="space-y-5">
<details class="rounded-2xl border border-slate-200 bg-white p-5 shadow-sm" open><summary class="cursor-pointer font-bold">Catat {{ kindName(kind).toLowerCase() }}</summary>
<form class="mt-5 grid gap-4 sm:grid-cols-2 lg:grid-cols-3" @submit.prevent="post(`/lifecycle/${kind}`)">
<label v-if="['maintenance','mutations','valuation','utilization','safeguarding'].includes(kind)" class="text-sm font-semibold">Aset<select v-model="form.asset_id" required class="mt-1.5 w-full rounded-lg border px-3 py-2.5"><option value="">Pilih aset</option><option v-for="asset in assets" :key="asset.id" :value="asset.id">{{ asset.asset_code||'Tanpa kode' }}  -  {{ asset.name }}</option></select></label>
<template v-if="kind==='maintenance'"><label class="text-sm font-semibold">Jenis pemeliharaan<input v-model="form.maintenance_type" required class="mt-1.5 w-full rounded-lg border px-3 py-2.5" placeholder="Preventif, perbaikan, servis"></label><label class="text-sm font-semibold">Rencana tanggal<input v-model="form.planned_at" type="date" class="mt-1.5 w-full rounded-lg border px-3 py-2.5"></label><label class="text-sm font-semibold">Perkiraan biaya<input v-model="form.planned_cost" type="number" min="0" class="mt-1.5 w-full rounded-lg border px-3 py-2.5"></label></template>
<template v-if="kind==='mutations'"><label class="text-sm font-semibold">Lokasi tujuan<select v-model="form.destination_location_id" required class="mt-1.5 w-full rounded-lg border px-3 py-2.5"><option value="">Pilih lokasi</option><option v-for="location in locations" :key="location.id" :value="location.id">{{ location.code }}  -  {{ location.name }}</option></select></label><label class="text-sm font-semibold">Jenis mutasi<input v-model="form.mutation_type" required class="mt-1.5 w-full rounded-lg border px-3 py-2.5"></label><label class="text-sm font-semibold">Tanggal efektif<input v-model="form.effective_at" type="date" required class="mt-1.5 w-full rounded-lg border px-3 py-2.5"></label><label class="text-sm font-semibold sm:col-span-2">Alasan<input v-model="form.reason" class="mt-1.5 w-full rounded-lg border px-3 py-2.5"></label></template>
<template v-if="kind==='valuation'"><label class="text-sm font-semibold">Tujuan penilaian<input v-model="form.purpose" required class="mt-1.5 w-full rounded-lg border px-3 py-2.5"></label><label class="text-sm font-semibold">Tanggal penilaian<input v-model="form.valuation_date" type="date" required class="mt-1.5 w-full rounded-lg border px-3 py-2.5"></label><label class="text-sm font-semibold">Nilai (Rp)<input v-model="form.amount" type="number" min="0" required class="mt-1.5 w-full rounded-lg border px-3 py-2.5"></label><label class="text-sm font-semibold">Penilai<input v-model="form.valuer_name" required class="mt-1.5 w-full rounded-lg border px-3 py-2.5"></label></template>
<template v-if="kind==='utilization'"><label class="text-sm font-semibold">Jenis pemanfaatan<input v-model="form.utilization_type" required class="mt-1.5 w-full rounded-lg border px-3 py-2.5"></label><label class="text-sm font-semibold">Mulai<input v-model="form.start_at" type="date" required class="mt-1.5 w-full rounded-lg border px-3 py-2.5"></label></template>
<template v-if="kind==='safeguarding'"><label class="text-sm font-semibold">Kategori pengamanan<input v-model="form.safeguard_category" required class="mt-1.5 w-full rounded-lg border px-3 py-2.5" placeholder="Administratif / fisik / hukum"></label></template>
<template v-if="['transfers','disposals'].includes(kind)"><fieldset class="sm:col-span-2 lg:col-span-3"><legend class="text-sm font-semibold">Pilih aset</legend><div class="mt-2 grid max-h-56 gap-2 overflow-y-auto rounded-xl border p-3 sm:grid-cols-2 lg:grid-cols-3"><label v-for="asset in assets" :key="asset.id" class="flex gap-2 rounded-lg p-2 hover:bg-slate-50"><input v-model="form.asset_ids" type="checkbox" :value="asset.id"><span class="text-sm">{{ asset.asset_code||'Tanpa kode' }}  -  {{ asset.name }}</span></label></div></fieldset><label v-if="kind==='transfers'" class="text-sm font-semibold">Jenis pemindahan<select v-model="form.transfer_type" class="mt-1.5 w-full rounded-lg border px-3 py-2.5"><option value="EXCHANGE">Tukar menukar</option><option value="SALE">Penjualan</option></select></label><template v-if="kind==='disposals'"><label class="text-sm font-semibold">Jenis penghapusan<input v-model="form.disposal_type" required class="mt-1.5 w-full rounded-lg border px-3 py-2.5"></label><label class="text-sm font-semibold">Alasan<input v-model="form.reason" required class="mt-1.5 w-full rounded-lg border px-3 py-2.5"></label></template></template>
<template v-if="kind==='usage'"><label class="text-sm font-semibold">Tahun penetapan<input v-model="form.period_year" type="number" required class="mt-1.5 w-full rounded-lg border px-3 py-2.5"></label><label class="text-sm font-semibold">Nomor keputusan<input v-model="form.decision_number" class="mt-1.5 w-full rounded-lg border px-3 py-2.5"></label></template>
<div class="flex items-end"><button :disabled="form.processing" class="w-full rounded-lg bg-[#0B2E5B] px-4 py-2.5 font-bold text-white disabled:opacity-50">{{ form.processing?'Menyimpan...':'Simpan' }}</button></div>
</form></details>
<section class="overflow-hidden rounded-2xl border bg-white shadow-sm"><div class="border-b px-5 py-4"><h2 class="font-bold">Riwayat {{ kindName(kind).toLowerCase() }}</h2></div><article v-for="item in items?.data" :key="item.id" class="flex flex-wrap items-center justify-between gap-4 border-b p-5 last:border-0"><div><strong>{{ item.name||item.maintenance_type||item.transfer_type||item.disposal_type||item.purpose||kindName(kind) }}</strong><p class="mt-1 text-sm text-slate-500">{{ label(item.status||item.effective_at||item.created_at) }}</p></div><form v-if="kind==='maintenance'&&item.status!=='completed'" @submit.prevent="post(`/lifecycle/${kind}/${item.id}/execute`)"><button class="rounded-lg border px-3 py-2 text-sm font-semibold">Tandai selesai</button></form><form v-if="kind==='usage'&&item.status==='draft'" @submit.prevent="post(`/lifecycle/${kind}/${item.id}/execute`)"><button class="rounded-lg border px-3 py-2 text-sm font-semibold">Finalisasi</button></form></article><p v-if="!items?.data?.length" class="p-10 text-center text-slate-500">Belum ada data {{ kindName(kind).toLowerCase() }}.</p></section>
</section>

<p v-else class="rounded-2xl border bg-white p-10 text-center text-slate-500">Belum ada data untuk halaman ini.</p>
</main></template>